##### KMP 算法
核心在于：最长相等的前后缀，构建前缀表： ![[Pasted image 20250225104258.png]] 匹配过程： ![[KMP精讲2.gif]] 实现算法：
```cpp
vector<int> buildNext(const string& pattern) {
    int n = pattern.size();
    vector<int> next(n, 0);
    // j指向最长公共前缀的最后一个字符，也表示最长公共前后缀长度
    for (int i = 1, j = 0; i < n; ++i) { // i指向现在匹配的位置，也是最长公共前后缀的字符串**后面**的一个字符
        // 如果不匹配（在试探延长前后缀字符串过程中发现不匹配并且j没有已经回退到0（回退到0不能再退了）
        while (j > 0 && pattern[i] != pattern[j]) {
            j = next[j - 1]; // 回退
        }
        // 匹配上了就换下一个模式串字符继续匹配，下一轮i++
        if (pattern[i] == pattern[j]) {
            ++j;
        }
        next[i] = j; // 更新next数组
    }
    return next;
}
int strStr(string text, string pattern) {
    if (pattern.empty()) {
        return 0;
    }
    vector<int> next = buildNext(pattern);
    int m = text.size(), n = pattern.size();
    for (int i = 0, j = 0; i < m; ++i) {
        // 如果模式串和匹配串中一个字符没有匹配上，并且模式串还能够回退
        while (j > 0 && text[i] != pattern[j]) {
            j = next[j - 1]; // 回退，回退的是指针而不是让数组移动
        }
        // 匹配上了就继续看下一个匹配上没
        if (text[i] == pattern[j]) {
            ++j;
        }
        // 如果没有下一个
        if (j == n) {
            return i - n + 1; // 结束，返回匹配串中第一个出现模式串的位置
        }
    }
    return -1;
}
```
库函数算法实现：
```cpp
int returnPos(string haystack, string needle) {
    return haystack.find(needle, 0);
}
```

